import { useCallback, useEffect, useRef, useState } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [ui, setUi] = useState({ results: [], phase: "idle" });

  const valueRef = useRef("");
  const timerRef = useRef(null);
  const requestRef = useRef(null);
  const mountedRef = useRef(false);

  const clearTimer = useCallback(() => {
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const clearSearch = useCallback(() => {
    clearTimer();

    const previous = requestRef.current;
    requestRef.current = null;
    if (previous) {
      previous.controller.abort();
    }

    setUi({ results: [], phase: "idle" });
  }, [clearTimer]);

  const startSearch = useCallback(
    async (query, force = false) => {
      if (!mountedRef.current) return;

      const previous = requestRef.current;
      if (
        !force &&
        previous &&
        previous.query === query &&
        !previous.controller.signal.aborted &&
        (previous.phase === "loading" || previous.phase === "success")
      ) {
        return;
      }

      const controller = new AbortController();
      const request = { query, controller, phase: "loading" };

      // Invalidate the previous request before aborting its signal.
      requestRef.current = request;
      if (previous) {
        previous.controller.abort();
      }

      setUi((current) => ({
        results: current.results,
        phase: "loading",
      }));

      const isCurrent = () =>
        mountedRef.current &&
        requestRef.current === request &&
        !controller.signal.aborted;

      try {
        const results = await search(query, { signal: controller.signal });
        if (!isCurrent()) return;

        request.phase = "success";
        setUi({ results, phase: "success" });
      } catch (error) {
        if (!isCurrent()) return;

        if (error?.name === "AbortError") {
          request.phase = "aborted";
          setUi((current) => ({
            results: current.results,
            phase: "idle",
          }));
        } else {
          request.phase = "error";
          setUi({ results: [], phase: "error" });
        }
      }
    },
    [search]
  );

  const scheduleSearch = useCallback(
    (rawValue) => {
      clearTimer();

      const query = rawValue.trim();
      if (query.length < minChars) {
        clearSearch();
        return;
      }

      timerRef.current = setTimeout(() => {
        timerRef.current = null;
        void startSearch(query);
      }, debounceMs);
    },
    [clearTimer, clearSearch, debounceMs, minChars, startSearch]
  );

  useEffect(() => {
    mountedRef.current = true;

    return () => {
      mountedRef.current = false;
      clearTimer();

      const previous = requestRef.current;
      requestRef.current = null;
      if (previous) {
        previous.controller.abort();
      }
    };
  }, [clearTimer]);

  // Also apply the current settings on mount and when the props change.
  useEffect(() => {
    scheduleSearch(valueRef.current);
    return clearTimer;
  }, [scheduleSearch, clearTimer]);

  function handleChange(event) {
    const nextValue = event.target.value;
    valueRef.current = nextValue;
    setValue(nextValue);
    scheduleSearch(nextValue);
  }

  function handleRetry() {
    clearTimer();

    const query = valueRef.current.trim();
    if (query.length < minChars) {
      clearSearch();
      return;
    }

    void startSearch(query, true);
  }

  const statusText =
    ui.phase === "loading"
      ? "Searching..."
      : ui.phase === "success" && ui.results.length === 0
        ? "No results"
        : "";

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{statusText}</div>
      <ul aria-label="Results">
        {ui.results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
      {ui.phase === "error" && (
        <div role="alert">
          Something went wrong
          <button type="button" onClick={handleRetry}>
            Retry
          </button>
        </div>
      )}
    </div>
  );
}
